class Solution { public: int minSwapsCouples(vector<int>& row){vector<int> position(row.size());for(int i=0;i<(int)row.size();++i)position[row[i]]=i;int answer=0;for(int i=0;i<(int)row.size();i+=2){int partner=row[i]^1;if(row[i+1]==partner)continue;int partnerSeat=position[partner],displaced=row[i+1];row[partnerSeat]=displaced;row[i+1]=partner;position[displaced]=partnerSeat;position[partner]=i+1;++answer;}return answer;} };
